import React from 'react';
import { Line, Bar, Pie } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, ArcElement } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, ArcElement);

export default function ChartComponent() {
  const lineData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{ label: 'Enrollment Growth', data: [10, 30, 25, 45, 80], borderColor: '#1976d2', fill: false }]
  };

  const barData = {
    labels: ['Fees', 'Payments'],
    datasets: [{ label: 'Revenue', data: [50, 30], backgroundColor: ['#1976d2', '#64b5f6'] }]
  };

  return (
  <div style={{ display: 'flex', gap: '20px' }}>
    {/* Bar Chart එක (Teacher Performance සඳහා) */}
    <div style={{ width: '400px' }}>
      <Bar data={barData} /> 
    </div>

    {/* Pie Chart එක (Class Distribution සඳහා) */}
    <div style={{ width: '300px' }}>
      <Pie data={{
        labels: ['Math', 'Science', 'English', 'History', 'IT'],
        datasets: [{
          data: [30, 25, 15, 20, 10], // ඔයාට ඕන පර්සන්ටේජ් එක
          backgroundColor: ['#007bff', '#28a745', '#ffc107', '#dc3545', '#17a2b8']
        }]
      }} />
    </div>
  </div>
);
}
